static bool ss_mapa_quitar_mapa_str_lista_str(ss_mapa_str_lista_str* p, SafeView clave)
{
    if (p->capacidad == 0) return false;
    size_t mascara = p->capacidad - 1;
    size_t i = ss_mapa_sitio_mapa_str_lista_str(p, clave);
    if (p->claves[i].data == NULL) return false;

    ss_free(&p->claves[i]);
    p->claves[i] = ss_new();
    for (size_t ss_i2 = 0; ss_i2 < p->valores[i].length; ss_i2++)
    {
        ss_free(&p->valores[i].e[ss_i2]);
    }
    free(p->valores[i].e);
    p->valores[i].e = NULL;
    p->valores[i].length = 0;
    p->valores[i].capacity = 0;
    memset(&p->valores[i], 0, sizeof(ss_lista_str));
    p->largo--;

    /* Sin lapidas: se cierra el hueco arrastrando hacia atras
       las entradas del mismo grupo que quedarian inalcanzables.
       Es lo que permite que la busqueda pueda parar en la
       primera celda libre. */
    size_t j = i;
    for (;;)
    {
        j = (j + 1) & mascara;
        if (p->claves[j].data == NULL) break;
        size_t k = (size_t) sv_hash(ss_view(&p->claves[j])) & mascara;
        bool mover = (i <= j) ? (k <= i || k > j)
                              : (k <= i && k > j);
        if (mover)
        {
            p->claves[i] = p->claves[j];
            p->valores[i] = p->valores[j];
            p->claves[j] = ss_new();
            i = j;
        }
    }
    return true;
}

